inputs.citizen_schema:
@prefix : <http://example.org/schema#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

# CORE ENTITY
:Person a rdfs:Class ;
    rdfs:comment "A human individual." .

:Applicant a rdfs:Class ;
    rdfs:subClassOf :Person ;
    rdfs:comment "A person actively applying for the parental leave allowance. Used as the Focus Node for SHACL validation." .

#  Basic Attributes 
:birthDate a rdf:Property ;
    rdfs:domain :Person ;
    rdfs:range xsd:date ;
    rdfs:comment "Used to calculate age (e.g., for the child)." .

#  Relationships 
:hasChild a rdf:Property ;
    rdfs:domain :Person ;
    rdfs:range :Person ;
    rdfs:comment "Links a parent to their child." .

# EMPLOYMENT STATUS
:EmploymentRecord a rdfs:Class ;
    rdfs:comment "A record of an active or past employment contract." .

:hasEmployment a rdf:Property ;
    rdfs:domain :Person ;
    rdfs:range :EmploymentRecord ;
    rdfs:comment "Links the applicant to their job details." .

#  Employment Properties 
:employmentSector a rdf:Property ;
    rdfs:domain :EmploymentRecord ;
    rdfs:range xsd:string ;
    rdfs:comment "The sector of employment. Expected values: 'Private', 'Public', 'Freelance' etc." .

:employmentStartDate a rdf:Property ;
    rdfs:domain :EmploymentRecord ;
    rdfs:range xsd:date ;
    rdfs:comment "The date the current employment or continuous contract series began." .

:isActive a rdf:Property ;
    rdfs:domain :EmploymentRecord ;
    rdfs:range xsd:boolean ;
    rdfs:comment "True if the employment is currently active." .

inputs.golden_citizen:
@prefix : <http://example.org/schema#> .
@prefix ex: <http://example.org/> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

# THE APPLICANT 
ex:Dimitris a :Applicant, :Person ;
    # Personal Info
    :birthDate "1990-05-15"^^xsd:date ; # 35 Years old
    :hasChild ex:Nikolas ;    
    # Employment Status
    :hasEmployment ex:DimitrisJob .

# THE CHILD 
ex:Nikolas a :Person ;
    :birthDate "2022-03-10"^^xsd:date . 

# EMPLOYMENT RECORD
ex:DimitrisJob a :EmploymentRecord ;
    :employmentSector "Private" ;
    :isActive true ;
    :employmentStartDate "2023-01-01"^^xsd:date .

messages.content:
@prefix : <http://example.org/schema#> .
@prefix ex: <http://example.org/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .

ex:working_parent_or_parental_responsibility_shape
    a sh:NodeShape ;
    sh:targetClass :Applicant ;
    sh:sparql [
        a sh:SPARQLConstraint ;
        sh:message "The applicant must have a child and an active employment relationship." ;
        sh:select """
            PREFIX : <http://example.org/schema#>
            SELECT ?this
            WHERE {
                FILTER NOT EXISTS {
                    ?this :hasChild ?child .
                    ?this :hasEmployment ?employment .
                    ?employment :isActive ?activeStatus .
                    FILTER (?activeStatus = true)
                }
            }
        """ ;
    ] .

ex:child_age_shape
    a sh:NodeShape ;
    sh:targetClass :Applicant ;
    sh:sparql [
        a sh:SPARQLConstraint ;
        sh:message "The applicant must have at least one child who is under eight years of age." ;
        sh:select """
            PREFIX : <http://example.org/schema#>
            SELECT ?this
            WHERE {
                FILTER NOT EXISTS {
                    ?this :hasChild ?child .
                    ?child :birthDate ?birthDate .
                    FILTER ((YEAR(now()) - YEAR(?birthDate)) < 8)
                }
            }
        """ ;
    ] .

ex:eligible_employment_relationship_shape
    a sh:NodeShape ;
    sh:targetClass :Applicant ;
    sh:sparql [
        a sh:SPARQLConstraint ;
        sh:message "The applicant must have an active employment relationship in the private or public sector." ;
        sh:select """
            PREFIX : <http://example.org/schema#>
            SELECT ?this
            WHERE {
                FILTER NOT EXISTS {
                    ?this :hasEmployment ?employment .
                    ?employment :isActive ?activeStatus .
                    ?employment :employmentSector ?sector .
                    FILTER (?activeStatus = true)
                    FILTER (?sector = "Private" || ?sector = "Public")
                }
            }
        """ ;
    ] .

ex:one_year_same_employer_shape
    a sh:NodeShape ;
    sh:targetClass :Applicant ;
    sh:sparql [
        a sh:SPARQLConstraint ;
        sh:message "The applicant must have at least twelve months of active employment from the recorded employment start date." ;
        sh:select """
            PREFIX : <http://example.org/schema#>
            SELECT ?this
            WHERE {
                FILTER NOT EXISTS {
                    ?this :hasEmployment ?employment .
                    ?employment :isActive ?activeStatus .
                    ?employment :employmentStartDate ?startDate .
                    FILTER (?activeStatus = true)
                    FILTER (
                        ((YEAR(now()) * 12 + MONTH(now())) -
                         (YEAR(?startDate) * 12 + MONTH(?startDate))) >= 12
                    )
                }
            }
        """ ;
    ] .

